def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize 2D DP arrays for both paths
    dp_left = [[0] * N for _ in range(N)]
    dp_right = [[0] * N for _ in range(N)]

    # Populate the dp arrays for the first path
    for i in range(N):
        if grid_values[i][2] > 0:
            dp_left[0][i] = grid_values[i][2]

    # Fill the dp arrays using the first path
    for i in range(1, N):
        for j in range(N):
            if grid_values[i][1] == j - 1 and grid_values[i][0] == i - 1:
              dp_left[i][j] = grid_values[i][2] + dp_left[i-1][j-1]
            else:
              dp_left[i][j] = max(grid_values[i][2] + dp_left[i-1][j], dp_left[i][j-1])

    # Populate the dp arrays for the second path
    for i in range(N):
        if grid_values[i][2] > 0:
            dp_right[i][N-1] = grid_values[i][2]

    # Fill the dp arrays using the second path
    for i in range(N-1, -1, -1):
        for j in range(N):
            if grid_values[i][1] == j + 1 and grid_values[i][0] == i + 1:
              dp_right[i][j] = grid_values[i][2] + dp_right[i+1][j+1]
            else:
              dp_right[i][j] = max(grid_values[i][2] + dp_right[i+1][j], dp_right[i][j+1])

    # Start the second path from the bottom-right corner, exploring from both directions
    max_path_sum = 0
    for i in range(N):
        for j in range(N):
            path_sum_left = dp_left[i][j] if i == 0 else dp_left[i-1][j] + grid_values[i][0]
            path_sum_right = dp_right[i][N-1-j] if j == 0 else dp_right[i][N-2-j] + grid_values[i][1]
            max_path_sum = max(max_path_sum, path_sum_left, path_sum_right)

    return max_path_sum

