def largest_prime_factor(n: int) -> int:
    if n < 2:
        return None  # No prime factors for numbers less than 2

    largest_prime = None
    factor = 2

    while factor * factor <= n:
        while n % factor == 0:
            largest_prime = factor
            n //= factor
        factor += 1

    if n > 1:
        largest_prime = n

    return largest_prime

def count_partitions(n: int, k: int, x: int) -> int:
    # Base case: if k=1, there's only one way to partition n
    if k == 1:
        return 1

    # Initialize a list to store the number of ways to partition each possible value from x to n-k+1
    dp = [0] * (n - x + 1)
    dp[x] = 1  # There's one way to partition x (the single part is x itself)

    # Fill the dp list
    for i in range(x, n + 1):
        for j in range(1, min(i, k) + 1):
            dp[i] += dp[i - j]

    return dp[n - x]

