    dp[0][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            dp[i][j] += sum(dp[i - x][j - 1] for x in range(1, min(i, x) + 1))

    return dp[n][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
