def preorder_traversal(self, inorder: str, postorder: str) -> str:
        """
        Reconstructs the binary tree from its inorder and postorder traversals and
        returns the preorder traversal as a string.

        :param inorder: The inorder traversal of the binary tree.
        :param postorder: The postorder traversal of the binary tree.
        :return: The preorder traversal of the binary tree.
        """
        in_map, post_map = {}, {}
        for i, c in enumerate(inorder):
            in_map[c] = i
        for i, c in enumerate(postorder):
            post_map[c] = i

        stack = [TreeNode(postorder[-1])]
        root = post_map[postorder[-1]]
        in_list = list(inorder)

        while stack:
            node = stack.pop()
            if node.left:
                if in_map[node.left] < in_map[root]:
                    stack.append(node.left)
                    in_list.remove(node.left.val)
            if node.right:
                if in_map[node.right] > in_map[root]:
                    stack.append(node.right)
                    in_list.remove(node.right.val)

        preorder = ''.join([str(node.val) for node in in_list])
        return preorder

