def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    def helper(index: int, time_remaining: int, current_value: int) -> int:
        if index == M or time_remaining == 0:
            return current_value

        # Skip picking the current herb
        skip_value = helper(index + 1, time_remaining, current_value)

        # Pick the current herb and update time remaining
        pick_value = current_value + herbs[index][1]
        remaining_time = time_remaining - herbs[index][0]
        if remaining_time >= 0:
            pick_value = helper(index + 1, remaining_time, pick_value)

        return max(skip_value, pick_value)

    return helper(0, T, 0)

