def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    Args:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (List[int]): A list of the volumes of the n items.

    Returns:
    - int: The minimum remaining space in the box after fitting the items.

    Examples:
    - min_remaining_space(24, 6, [8, 3, 12, 7, 9, 7]) -> 0
    - min_remaining_space(5, 3, [6, 7, 8]) -> 5
    """

    @lru_cache(None)
    def dp(i, used):
        if used == n:
            return 0
        if i == len(volumes):
            return V
        take = volumes[i] + dp(i + 1, used + 1)
        dont_take = dp(i + 1, used)
        return min(take, dont_take)

    return V - dp(0, 0)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize the memoization table
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Fill the memoization table
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i-1] <= j:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-volumes[i-1]] + volumes[i-1])
            else:
                dp[i][j] = dp[i-1][j]

    # The maximum volume that can be occupied is in the last cell of the table
    max_occupied_volume = dp[n][V]

    # Calculate the minimum remaining space
    min_remaining_space = V - max_occupied_volume

    return min_remaining_space

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a list to store the maximum occupied volume for each subset of items
    dp = [0] * (V + 1)

    # Iterate through each item and update the dp table
    for volume in volumes:
        for i in range(V, volume - 1, -1):
            dp[i] = max(dp[i], dp[i - volume] + volume)

    # The remaining space is the difference between the box's total capacity and the maximum occupied volume
    return V - dp[V]

