def vigenere_decrypt(key: str, ciphertext: str) -> str:
    key_length = len(key)
    alphabet = "abcdefghijklmnopqrstuvwxyz"

    # Ensure key is at least as long as the ciphertext for valid decryption
    if len(key) < len(ciphertext):
        raise ValueError("The key must be at least as long as the ciphertext.")

    decrypted_chars = []

    for i, char in enumerate(ciphertext):
        shift = alphabet.index(key[i % key_length])
        if char.isalpha():
            offset = -shift if char.isupper() else shift
            decrypted_char = alphabet[(alphabet.index(char) + offset) % 26]
        else:
            decrypted_char = char
        decrypted_chars.append(decrypted_char)

    return ''.join(decrypted_chars)

