def next_permutation(perm: list) -> bool:
    i = len(perm) - 2
    while i >= 0 and perm[i] >= perm[i + 1]:
        i -= 1

    if i == -1:
        return False

    j = len(perm) - 1
    while perm[j] <= perm[i]:
        j -= 1

    perm[i], perm[j] = perm[j], perm[i]
    perm[i + 1 :] = perm[i + 1 :][::-1]

    return True

