def hanoi_double_iterative(n: int) -> int:
    # Base cases for the recursive relation
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14

    # Recursive relation for n > 3
    return 2 * hanoi_double_iterative(n-1) + 2 * n
